1	// Package chainledger implements the on-chain data governance core.
2	package chainledger
3	
4	import (
5		"encoding/json"
6		"fmt"
7		"sort"
8		"strings"
9	)
10	
11	// PlanChange is one record in a lineage adjustment plan: the dataset name and
12	// the complete list of its direct upstreams after the batch is applied.
13	//
14	// A change may name a dataset that does not exist yet (it is registered) or an
15	// existing dataset (its direct upstreams are replaced wholesale). Datasets not
16	// mentioned in the plan keep their current direct upstreams.
17	type PlanChange struct {
18		Name      string   `json:"name"`
19		Upstreams []string `json:"upstreams"`
20	}
21	
22	// Plan is a batch of lineage adjustments read from a JSON file.
23	//
24	// Removals names datasets that must be absent from the final graph. Deleting a
25	// name that does not currently exist is a no-op (it is not reported as an
26	// actual removal), so a successful plan can be applied again with empty change
27	// and impact lists. A name listed in Removals must not also appear in Changes.
28	type Plan struct {
29		Changes  []PlanChange `json:"changes"`
30		Removals []string     `json:"removals"`
31	}
32	
33	// Relation is a directed lineage edge: Upstream -> Downstream, meaning the
34	// downstream dataset derives from the upstream dataset.
35	type Relation struct {
36		Upstream   string `json:"upstream"`
37		Downstream string `json:"downstream"`
38	}
39	
40	// GraphDataset is one dataset record in the on-disk graph JSON.
41	type GraphDataset struct {
42		Name      string   `json:"name"`
43		Upstreams []string `json:"upstreams"`
44	}
45	
46	// GraphFile is the on-disk JSON representation of a lineage graph.
47	type GraphFile struct {
48		Datasets []GraphDataset `json:"datasets"`
49	}
50	
51	// BatchReport is the deterministic report produced by preview and apply.
52	//
53	// All slices are non-nil (empty lists encode as [] in JSON). Datasets and name
54	// lists are sorted by name byte order; relation lists are sorted by upstream
55	// then downstream.
56	type BatchReport struct {
57		FinalGraph          GraphFile  `json:"finalGraph"`
58		NewDatasets         []string   `json:"newDatasets"`
59		ChangedDatasets     []string   `json:"changedDatasets"`
60		RemovedDatasets     []string   `json:"removedDatasets"`
61		AddedRelations      []Relation `json:"addedRelations"`
62		RemovedRelations    []Relation `json:"removedRelations"`
63		AffectedDownstreams []string   `json:"affectedDownstreams"`
64	}
65	
66	// adjacency maps a dataset name to its sorted, duplicate-free parent names.
67	type adjacency map[string][]string
68	
69	// graphAdjacency derives the parent map from the in-memory graph. It rejects
70	// nil lineage nodes, empty names, and references to upstreams that are not
71	// registered. It does not check for cycles; use validateAcyclic for that.
72	func graphAdjacency(graph map[string]*Lineage) (adjacency, error) {
73		if graph == nil {
74			return nil, fmt.Errorf("%w: create the graph map with make before validating", ErrNotInitialized)
75		}
76		adj := make(adjacency, len(graph))
77		for name, entry := range graph {
78			if entry == nil {
79				return nil, fmt.Errorf("%w: dataset %q points to a nil lineage node", ErrInvalidArgument, name)
80			}
81			if name == "" {
82				return nil, fmt.Errorf("%w: dataset name is required", ErrInvalidArgument)
83			}
84			parents := uniqueSorted(entry.Parents)
85			for _, parent := range parents {
86				if _, ok := graph[parent]; !ok {
87					return nil, fmt.Errorf("%w: dataset %q references upstream %q which is not registered", ErrNotFound, name, parent)
88				}
89			}
90			adj[name] = parents
91		}
92		return adj, nil
93	}
94	
95	// ValidateGraph checks the in-memory graph for structural problems: nil nodes,
96	// empty names, missing upstreams, and cycles. It does not mutate the graph.
97	//
98	// A graph that fails validation cannot be used as the basis for a batch: an
99	// adjustment plan must not be allowed to paper over pre-existing corruption.
100	func ValidateGraph(graph map[string]*Lineage) error {
101		adj, err := graphAdjacency(graph)
102		if err != nil {
103			return err
104		}
105		return validateAcyclic(adj)
106	}
107	
108	// validateAcyclic reports an error if the parent adjacency contains a cycle
109	// (including a dataset that depends on itself). The error message names the
110	// datasets involved.
111	func validateAcyclic(adj adjacency) error {
112		const (
113			white = 0
114			gray  = 1
115			black = 2
116		)
117		color := make(map[string]int, len(adj))
118		var stack []string
119	
120		var dfs func(node string) error
121		dfs = func(node string) error {
122			color[node] = gray
123			stack = append(stack, node)
124			for _, parent := range adj[node] {
125				switch color[parent] {
126				case gray:
127					// parent is an ancestor of node in the current DFS path, so
128					// following parent edges from parent leads back to parent.
129					idx := 0
130					for stack[idx] != parent {
131						idx++
132					}
133					cycle := make([]string, 0, len(stack)-idx+1)
134					cycle = append(cycle, stack[idx:]...)
135					cycle = append(cycle, parent)
136					return fmt.Errorf("%w: dependency cycle %s", ErrCycle, strings.Join(cycle, " -> "))
137				case white:
138					if err := dfs(parent); err != nil {
139						return err
140					}
141				}
142			}
143			color[node] = black
144			stack = stack[:len(stack)-1]
145			return nil
146		}
147	
148		// Iterate over a sorted snapshot so the first reported cycle is stable
149		// across runs regardless of map iteration order.
150		names := make([]string, 0, len(adj))
151		for name := range adj {
152			names = append(names, name)
153		}
154		sort.Strings(names)
155		for _, name := range names {
156			if color[name] == white {
157				if err := dfs(name); err != nil {
158					return err
159				}
160			}
161		}
162		return nil
163	}
164	
165	// computeBatch validates the graph and plan, then computes the final adjacency
166	// and the diff report. It does not mutate graph. The returned adjacency is the
167	// graph as it will be after the batch; callers that want to commit it should
168	// pass it to applyAdjacency.
169	func computeBatch(graph map[string]*Lineage, plan Plan) (*BatchReport, adjacency, error) {
170		if err := ValidateGraph(graph); err != nil {
171			return nil, nil, err
172		}
173		original, err := graphAdjacency(graph)
174		if err != nil {
175			return nil, nil, err
176		}
177	
178		// Validate the plan: empty names and duplicate declarations reject the
179		// whole batch, naming the dataset and the reason.
180		declarations := make(map[string]int, len(plan.Changes))
181		for _, change := range plan.Changes {
182			if change.Name == "" {
183				return nil, nil, fmt.Errorf("%w: plan contains a dataset with an empty name", ErrInvalidArgument)
184			}
185			declarations[change.Name]++
186			if declarations[change.Name] > 1 {
187				return nil, nil, fmt.Errorf("%w: dataset %q is declared %d times in the plan", ErrInvalidArgument, change.Name, declarations[change.Name])
188			}
189		}
190	
191		// Validate removals: empty names, duplicate names, and names also declared
192		// as changes all reject the whole batch with the name and reason.
193		removalDecls := make(map[string]int, len(plan.Removals))
194		for _, name := range plan.Removals {
195			if name == "" {
196				return nil, nil, fmt.Errorf("%w: plan removals contain a dataset with an empty name", ErrInvalidArgument)
197			}
198			removalDecls[name]++
199			if removalDecls[name] > 1 {
200				return nil, nil, fmt.Errorf("%w: dataset %q is listed %d times in removals", ErrInvalidArgument, name, removalDecls[name])
201			}
202			if _, ok := declarations[name]; ok {
203				return nil, nil, fmt.Errorf("%w: dataset %q appears in both changes and removals", ErrInvalidArgument, name)
204			}
205		}
206	
207		// Build the final adjacency: start from the original parents, replace each
208		// planned dataset's parents with its normalized upstreams.
209		final := make(adjacency, len(original)+len(plan.Changes))
210		for name, parents := range original {
211			final[name] = append([]string(nil), parents...)
212		}
213		for name := range removalDecls {
214			delete(final, name)
215		}
216		var newNames []string
217		var changedNames []string
218		for _, change := range plan.Changes {
219			wanted := uniqueSorted(change.Upstreams)
220			old, existed := original[change.Name]
221			switch {
222			case !existed:
223				newNames = append(newNames, change.Name)
224			case !stringSliceEqual(old, wanted):
225				changedNames = append(changedNames, change.Name)
226			}
227			final[change.Name] = wanted
228		}
229		sort.Strings(newNames)
230		sort.Strings(changedNames)
231	
232		// Datasets actually removed: names in removals that existed in the
233		// original graph. Deleting a name that does not exist is a no-op and is
234		// not reported, so a successful plan can be applied again with empty lists.
235		var removedNames []string
236		for name := range removalDecls {
237			if _, existed := original[name]; existed {
238				removedNames = append(removedNames, name)
239			}
240		}
241		sort.Strings(removedNames)
242	
243		// Every upstream must resolve to a dataset that exists in the FINAL graph
244		// (new datasets may reference each other regardless of plan order; a
245		// retained dataset that still references a deleted name is rejected here,
246		// with both the referrer and the referenced name in the error). Iterate
247		// over sorted names so the reported pair is deterministic.
248		names := make([]string, 0, len(final))
249		for name := range final {
250			names = append(names, name)
251		}
252		sort.Strings(names)
253		for _, name := range names {
254			for _, parent := range final[name] {
255				if _, ok := final[parent]; !ok {
256					return nil, nil, fmt.Errorf("%w: dataset %q references upstream %q which does not exist in the final graph", ErrNotFound, name, parent)
257				}
258			}
259		}
260		// The final graph must be acyclic, judged after all replacements.
261		if err := validateAcyclic(final); err != nil {
262			return nil, nil, err
263		}
264	
265		added, removed := diffRelations(original, final)
266		affected := affectedDownstreams(original, final, newNames, changedNames, removedNames)
267	
268		report := &BatchReport{
269			FinalGraph:          GraphFile{Datasets: adjacencyToDatasets(final)},
270			NewDatasets:         newNames,
271			ChangedDatasets:      changedNames,
272			RemovedDatasets:     removedNames,
273			AddedRelations:      added,
274			RemovedRelations:    removed,
275			AffectedDownstreams: affected,
276		}
277		// Guarantee non-nil slices so JSON encodes empty lists as [].
278		if report.NewDatasets == nil {
279			report.NewDatasets = []string{}
280		}
281		if report.ChangedDatasets == nil {
282			report.ChangedDatasets = []string{}
283		}
284		if report.RemovedDatasets == nil {
285			report.RemovedDatasets = []string{}
286		}
287		if report.AddedRelations == nil {
288			report.AddedRelations = []Relation{}
289		}
290		if report.RemovedRelations == nil {
291			report.RemovedRelations = []Relation{}
292		}
293		if report.AffectedDownstreams == nil {
294			report.AffectedDownstreams = []string{}
295		}
296		return report, final, nil
297	}
298	
299	// PreviewBatch validates the graph and plan and returns the report WITHOUT
300	// mutating graph. Preview and apply for the same graph and plan produce
301	// identical reports.
302	func PreviewBatch(graph map[string]*Lineage, plan Plan) (*BatchReport, error) {
303		report, _, err := computeBatch(graph, plan)
304		return report, err
305	}
306	
307	// ApplyBatch validates the plan, applies it to graph, and returns the report.
308	// On rejection, graph is left completely unchanged.
309	func ApplyBatch(graph map[string]*Lineage, plan Plan) (*BatchReport, error) {
310		report, final, err := computeBatch(graph, plan)
311		if err != nil {
312			return nil, err
313		}
314		applyAdjacency(graph, final)
315		return report, nil
316	}
317	
318	// applyAdjacency rewrites the in-memory graph to match the final adjacency:
319	// nodes absent from final are removed, parents are replaced, and children are
320	// rebuilt from the parent edges.
321	func applyAdjacency(graph map[string]*Lineage, final adjacency) {
322		for name := range graph {
323			if _, ok := final[name]; !ok {
324				delete(graph, name)
325			}
326		}
327		for name, parents := range final {
328			entry := graph[name]
329			if entry == nil {
330				entry = &Lineage{}
331				graph[name] = entry
332			}
333			entry.Dataset = name
334			entry.Parents = append([]string(nil), parents...)
335			entry.Children = nil
336		}
337		for name, parents := range final {
338			for _, parent := range parents {
339				graph[parent].Children = append(graph[parent].Children, name)
340			}
341		}
342		for name := range graph {
343			graph[name].Children = uniqueSorted(graph[name].Children)
344		}
345	}
346	
347	// diffRelations returns the directed edges present in final but not original
348	// (added) and present in original but not final (removed). Both lists are
349	// sorted by upstream then downstream.
350	func diffRelations(original, final adjacency) (added, removed []Relation) {
351		origEdges := edgeSet(original)
352		finalEdges := edgeSet(final)
353		for e := range finalEdges {
354			if !origEdges[e] {
355				added = append(added, e)
356			}
357		}
358		for e := range origEdges {
359			if !finalEdges[e] {
360				removed = append(removed, e)
361			}
362		}
363		sortRelations(added)
364		sortRelations(removed)
365		return added, removed
366	}
367	
368	// edgeSet collapses the adjacency into a set of upstream->downstream edges.
369	func edgeSet(adj adjacency) map[Relation]bool {
370		set := make(map[Relation]bool)
371		for downstream, parents := range adj {
372			for _, upstream := range parents {
373				set[Relation{Upstream: upstream, Downstream: downstream}] = true
374			}
375		}
376		return set
377	}
378	
379	// sortRelations sorts by upstream then downstream.
380	func sortRelations(rels []Relation) {
381		sort.Slice(rels, func(i, j int) bool {
382			if rels[i].Upstream != rels[j].Upstream {
383				return rels[i].Upstream < rels[j].Upstream
384			}
385			return rels[i].Downstream < rels[j].Downstream
386		})
387	}
388	
389	// affectedDownstreams computes the impact set: starting from the seed datasets
390	// (new, actually changed, or actually removed), follow downstream (children)
391	// edges in BOTH the original and the final graphs. Datasets that are
392	// themselves seeds are excluded from the output; every other reachable dataset
393	// is included once.
394	//
395	// Walking both graphs matters when relations are deleted: a dataset that was
396	// reachable downstream before the change (and thus loses a lineage path) is
397	// still affected even if the edge is gone in the final graph. Removed datasets
398	// are seeds too, so a downstream that lost its upstream node is counted.
399	func affectedDownstreams(original, final adjacency, newNames, changedNames, removedNames []string) []string {
400		seeds := make(map[string]bool, len(newNames)+len(changedNames)+len(removedNames))
401		for _, name := range newNames {
402			seeds[name] = true
403		}
404		for _, name := range changedNames {
405			seeds[name] = true
406		}
407		for _, name := range removedNames {
408			seeds[name] = true
409		}
410	
411		origChildren := invertAdjacency(original)
412		finalChildren := invertAdjacency(final)
413	
414		seen := make(map[string]bool)
415		queue := make([]string, 0, len(seeds))
416		for seed := range seeds {
417			queue = append(queue, seed)
418		}
419		for len(queue) > 0 {
420			node := queue[0]
421			queue = queue[1:]
422			for _, child := range origChildren[node] {
423				if !seen[child] {
424					seen[child] = true
425					queue = append(queue, child)
426				}
427			}
428			for _, child := range finalChildren[node] {
429				if !seen[child] {
430					seen[child] = true
431					queue = append(queue, child)
432				}
433			}
434		}
435	
436		out := make([]string, 0, len(seen))
437		for name := range seen {
438			if !seeds[name] {
439				out = append(out, name)
440			}
441		}
442		sort.Strings(out)
443		return out
444	}
445	
446	// invertAdjacency maps each dataset to the datasets that depend on it (its
447	// children), with each child list sorted by name.
448	func invertAdjacency(adj adjacency) map[string][]string {
449		children := make(map[string][]string, len(adj))
450		for name, parents := range adj {
451			for _, parent := range parents {
452				children[parent] = append(children[parent], name)
453			}
454		}
455		for name := range children {
456			sort.Strings(children[name])
457		}
458		return children
459	}
460	
461	// adjacencyToDatasets renders the final adjacency as sorted, JSON-ready
462	// records with non-nil upstream lists.
463	func adjacencyToDatasets(adj adjacency) []GraphDataset {
464		names := make([]string, 0, len(adj))
465		for name := range adj {
466			names = append(names, name)
467		}
468		sort.Strings(names)
469		ds := make([]GraphDataset, 0, len(names))
470		for _, name := range names {
471			parents := adj[name]
472			if parents == nil {
473				parents = []string{}
474			}
475			ds = append(ds, GraphDataset{Name: name, Upstreams: parents})
476		}
477		return ds
478	}
479	
480	// stringSliceEqual reports whether a and b contain the same strings in the
481	// same order. Both are expected to be sorted and duplicate-free.
482	func stringSliceEqual(a, b []string) bool {
483		if len(a) != len(b) {
484			return false
485		}
486		for i := range a {
487			if a[i] != b[i] {
488				return false
489			}
490		}
491		return true
492	}
493	
494	// MarshalGraphFile serializes the in-memory graph to the on-disk JSON format.
495	// The graph must be valid; an invalid graph returns an error.
496	func MarshalGraphFile(graph map[string]*Lineage) ([]byte, error) {
497		adj, err := graphAdjacency(graph)
498		if err != nil {
499			return nil, err
500		}
501		gf := GraphFile{Datasets: adjacencyToDatasets(adj)}
502		return json.MarshalIndent(gf, "", "  ")
503	}
504	
505	// UnmarshalGraphFile parses the on-disk graph JSON, rebuilds the in-memory
506	// graph (parents and children), and validates it. A graph that is structurally
507	// invalid (empty names, duplicate datasets, missing upstreams, or cycles) is
508	// rejected so it cannot be used as the basis for a batch.
509	func UnmarshalGraphFile(data []byte) (map[string]*Lineage, error) {
510		var gf GraphFile
511		if err := json.Unmarshal(data, &gf); err != nil {
512			return nil, fmt.Errorf("invalid graph JSON: %w", err)
513		}
514		graph := make(map[string]*Lineage, len(gf.Datasets))
515		for _, ds := range gf.Datasets {
516			if ds.Name == "" {
517				return nil, fmt.Errorf("%w: graph contains a dataset with an empty name", ErrInvalidArgument)
518			}
519			if _, exists := graph[ds.Name]; exists {
520				return nil, fmt.Errorf("%w: dataset %q is declared more than once in the graph", ErrInvalidArgument, ds.Name)
521			}
522			graph[ds.Name] = &Lineage{Dataset: ds.Name, Parents: uniqueSorted(ds.Upstreams)}
523		}
524		// Rebuild children from the parent edges so the in-memory graph is
525		// consistent regardless of how the file was produced.
526		for name, entry := range graph {
527			for _, parent := range entry.Parents {
528				if parentNode, ok := graph[parent]; ok {
529					parentNode.Children = append(parentNode.Children, name)
530				}
531			}
532		}
533		for name := range graph {
534			graph[name].Children = uniqueSorted(graph[name].Children)
535		}
536		if err := ValidateGraph(graph); err != nil {
537			return nil, err
538		}
539		return graph, nil
540	}
541	
542	// UnmarshalPlan parses the plan JSON. The plan structure (empty names,
543	// duplicate declarations) is validated later by computeBatch so that preview
544	// and apply share identical rejection behavior.
545	func UnmarshalPlan(data []byte) (Plan, error) {
546		var p Plan
547		if err := json.Unmarshal(data, &p); err != nil {
548			return p, fmt.Errorf("invalid plan JSON: %w", err)
549		}
550		return p, nil
551	}
552

file.content:
// Package chainledger implements the on-chain data governance core.
package chainledger

import (
	"encoding/json"
	"fmt"
	"sort"
	"strings"
)

// PlanChange is one record in a lineage adjustment plan: the dataset name and
// the complete list of its direct upstreams after the batch is applied.
//
// A change may name a dataset that does not exist yet (it is registered) or an
// existing dataset (its direct upstreams are replaced wholesale). Datasets not
// mentioned in the plan keep their current direct upstreams.
type PlanChange struct {
	Name      string   `json:"name"`
	Upstreams []string `json:"upstreams"`
}

// Plan is a batch of lineage adjustments read from a JSON file.
//
// Removals names datasets that must be absent from the final graph. Deleting a
// name that does not currently exist is a no-op (it is not reported as an
// actual removal), so a successful plan can be applied again with empty change
// and impact lists. A name listed in Removals must not also appear in Changes.
type Plan struct {
	Changes  []PlanChange `json:"changes"`
	Removals []string     `json:"removals"`
}

// Relation is a directed lineage edge: Upstream -> Downstream, meaning the
// downstream dataset derives from the upstream dataset.
type Relation struct {
	Upstream   string `json:"upstream"`
	Downstream string `json:"downstream"`
}

// GraphDataset is one dataset record in the on-disk graph JSON.
type GraphDataset struct {
	Name      string   `json:"name"`
	Upstreams []string `json:"upstreams"`
}

// GraphFile is the on-disk JSON representation of a lineage graph.
type GraphFile struct {
	Datasets []GraphDataset `json:"datasets"`
}

// BatchReport is the deterministic report produced by preview and apply.
//
// All slices are non-nil (empty lists encode as [] in JSON). Datasets and name
// lists are sorted by name byte order; relation lists are sorted by upstream
// then downstream.
type BatchReport struct {
	FinalGraph          GraphFile  `json:"finalGraph"`
	NewDatasets         []string   `json:"newDatasets"`
	ChangedDatasets     []string   `json:"changedDatasets"`
	RemovedDatasets     []string   `json:"removedDatasets"`
	AddedRelations      []Relation `json:"addedRelations"`
	RemovedRelations    []Relation `json:"removedRelations"`
	AffectedDownstreams []string   `json:"affectedDownstreams"`
}

// adjacency maps a dataset name to its sorted, duplicate-free parent names.
type adjacency map[string][]string

// graphAdjacency derives the parent map from the in-memory graph. It rejects
// nil lineage nodes, empty names, and references to upstreams that are not
// registered. It does not check for cycles; use validateAcyclic for that.
func graphAdjacency(graph map[string]*Lineage) (adjacency, error) {
	if graph == nil {
		return nil, fmt.Errorf("%w: create the graph map with make before validating", ErrNotInitialized)
	}
	adj := make(adjacency, len(graph))
	for name, entry := range graph {
		if entry == nil {
			return nil, fmt.Errorf("%w: dataset %q points to a nil lineage node", ErrInvalidArgument, name)
		}
		if name == "" {
			return nil, fmt.Errorf("%w: dataset name is required", ErrInvalidArgument)
		}
		parents := uniqueSorted(entry.Parents)
		for _, parent := range parents {
			if _, ok := graph[parent]; !ok {
				return nil, fmt.Errorf("%w: dataset %q references upstream %q which is not registered", ErrNotFound, name, parent)
			}
		}
		adj[name] = parents
	}
	return adj, nil
}

// ValidateGraph checks the in-memory graph for structural problems: nil nodes,
// empty names, missing upstreams, and cycles. It does not mutate the graph.
//
// A graph that fails validation cannot be used as the basis for a batch: an
// adjustment plan must not be allowed to paper over pre-existing corruption.
func ValidateGraph(graph map[string]*Lineage) error {
	adj, err := graphAdjacency(graph)
	if err != nil {
		return err
	}
	return validateAcyclic(adj)
}

// validateAcyclic reports an error if the parent adjacency contains a cycle
// (including a dataset that depends on itself). The error message names the
// datasets involved.
func validateAcyclic(adj adjacency) error {
	const (
		white = 0
		gray  = 1
		black = 2
	)
	color := make(map[string]int, len(adj))
	var stack []string

	var dfs func(node string) error
	dfs = func(node string) error {
		color[node] = gray
		stack = append(stack, node)
		for _, parent := range adj[node] {
			switch color[parent] {
			case gray:
				// parent is an ancestor of node in the current DFS path, so
				// following parent edges from parent leads back to parent.
				idx := 0
				for stack[idx] != parent {
					idx++
				}
				cycle := make([]string, 0, len(stack)-idx+1)
				cycle = append(cycle, stack[idx:]...)
				cycle = append(cycle, parent)
				return fmt.Errorf("%w: dependency cycle %s", ErrCycle, strings.Join(cycle, " -> "))
			case white:
				if err := dfs(parent); err != nil {
					return err
				}
			}
		}
		color[node] = black
		stack = stack[:len(stack)-1]
		return nil
	}

	// Iterate over a sorted snapshot so the first reported cycle is stable
	// across runs regardless of map iteration order.
	names := make([]string, 0, len(adj))
	for name := range adj {
		names = append(names, name)
	}
	sort.Strings(names)
	for _, name := range names {
		if color[name] == white {
			if err := dfs(name); err != nil {
				return err
			}
		}
	}
	return nil
}

// computeBatch validates the graph and plan, then computes the final adjacency
// and the diff report. It does not mutate graph. The returned adjacency is the
// graph as it will be after the batch; callers that want to commit it should
// pass it to applyAdjacency.
func computeBatch(graph map[string]*Lineage, plan Plan) (*BatchReport, adjacency, error) {
	if err := ValidateGraph(graph); err != nil {
		return nil, nil, err
	}
	original, err := graphAdjacency(graph)
	if err != nil {
		return nil, nil, err
	}

	// Validate the plan: empty names and duplicate declarations reject the
	// whole batch, naming the dataset and the reason.
	declarations := make(map[string]int, len(plan.Changes))
	for _, change := range plan.Changes {
		if change.Name == "" {
			return nil, nil, fmt.Errorf("%w: plan contains a dataset with an empty name", ErrInvalidArgument)
		}
		declarations[change.Name]++
		if declarations[change.Name] > 1 {
			return nil, nil, fmt.Errorf("%w: dataset %q is declared %d times in the plan", ErrInvalidArgument, change.Name, declarations[change.Name])
		}
	}

	// Validate removals: empty names, duplicate names, and names also declared
	// as changes all reject the whole batch with the name and reason.
	removalDecls := make(map[string]int, len(plan.Removals))
	for _, name := range plan.Removals {
		if name == "" {
			return nil, nil, fmt.Errorf("%w: plan removals contain a dataset with an empty name", ErrInvalidArgument)
		}
		removalDecls[name]++
		if removalDecls[name] > 1 {
			return nil, nil, fmt.Errorf("%w: dataset %q is listed %d times in removals", ErrInvalidArgument, name, removalDecls[name])
		}
		if _, ok := declarations[name]; ok {
			return nil, nil, fmt.Errorf("%w: dataset %q appears in both changes and removals", ErrInvalidArgument, name)
		}
	}

	// Build the final adjacency: start from the original parents, replace each
	// planned dataset's parents with its normalized upstreams.
	final := make(adjacency, len(original)+len(plan.Changes))
	for name, parents := range original {
		final[name] = append([]string(nil), parents...)
	}
	for name := range removalDecls {
		delete(final, name)
	}
	var newNames []string
	var changedNames []string
	for _, change := range plan.Changes {
		wanted := uniqueSorted(change.Upstreams)
		old, existed := original[change.Name]
		switch {
		case !existed:
			newNames = append(newNames, change.Name)
		case !stringSliceEqual(old, wanted):
			changedNames = append(changedNames, change.Name)
		}
		final[change.Name] = wanted
	}
	sort.Strings(newNames)
	sort.Strings(changedNames)

	// Datasets actually removed: names in removals that existed in the
	// original graph. Deleting a name that does not exist is a no-op and is
	// not reported, so a successful plan can be applied again with empty lists.
	var removedNames []string
	for name := range removalDecls {
		if _, existed := original[name]; existed {
			removedNames = append(removedNames, name)
		}
	}
	sort.Strings(removedNames)

	// Every upstream must resolve to a dataset that exists in the FINAL graph
	// (new datasets may reference each other regardless of plan order; a
	// retained dataset that still references a deleted name is rejected here,
	// with both the referrer and the referenced name in the error). Iterate
	// over sorted names so the reported pair is deterministic.
	names := make([]string, 0, len(final))
	for name := range final {
		names = append(names, name)
	}
	sort.Strings(names)
	for _, name := range names {
		for _, parent := range final[name] {
			if _, ok := final[parent]; !ok {
				return nil, nil, fmt.Errorf("%w: dataset %q references upstream %q which does not exist in the final graph", ErrNotFound, name, parent)
			}
		}
	}
	// The final graph must be acyclic, judged after all replacements.
	if err := validateAcyclic(final); err != nil {
		return nil, nil, err
	}

	added, removed := diffRelations(original, final)
	affected := affectedDownstreams(original, final, newNames, changedNames, removedNames)

	report := &BatchReport{
		FinalGraph:          GraphFile{Datasets: adjacencyToDatasets(final)},
		NewDatasets:         newNames,
		ChangedDatasets:      changedNames,
		RemovedDatasets:     removedNames,
		AddedRelations:      added,
		RemovedRelations:    removed,
		AffectedDownstreams: affected,
	}
	// Guarantee non-nil slices so JSON encodes empty lists as [].
	if report.NewDatasets == nil {
		report.NewDatasets = []string{}
	}
	if report.ChangedDatasets == nil {
		report.ChangedDatasets = []string{}
	}
	if report.RemovedDatasets == nil {
		report.RemovedDatasets = []string{}
	}
	if report.AddedRelations == nil {
		report.AddedRelations = []Relation{}
	}
	if report.RemovedRelations == nil {
		report.RemovedRelations = []Relation{}
	}
	if report.AffectedDownstreams == nil {
		report.AffectedDownstreams = []string{}
	}
	return report, final, nil
}

// PreviewBatch validates the graph and plan and returns the report WITHOUT
// mutating graph. Preview and apply for the same graph and plan produce
// identical reports.
func PreviewBatch(graph map[string]*Lineage, plan Plan) (*BatchReport, error) {
	report, _, err := computeBatch(graph, plan)
	return report, err
}

// ApplyBatch validates the plan, applies it to graph, and returns the report.
// On rejection, graph is left completely unchanged.
func ApplyBatch(graph map[string]*Lineage, plan Plan) (*BatchReport, error) {
	report, final, err := computeBatch(graph, plan)
	if err != nil {
		return nil, err
	}
	applyAdjacency(graph, final)
	return report, nil
}

// applyAdjacency rewrites the in-memory graph to match the final adjacency:
// nodes absent from final are removed, parents are replaced, and children are
// rebuilt from the parent edges.
func applyAdjacency(graph map[string]*Lineage, final adjacency) {
	for name := range graph {
		if _, ok := final[name]; !ok {
			delete(graph, name)
		}
	}
	for name, parents := range final {
		entry := graph[name]
		if entry == nil {
			entry = &Lineage{}
			graph[name] = entry
		}
		entry.Dataset = name
		entry.Parents = append([]string(nil), parents...)
		entry.Children = nil
	}
	for name, parents := range final {
		for _, parent := range parents {
			graph[parent].Children = append(graph[parent].Children, name)
		}
	}
	for name := range graph {
		graph[name].Children = uniqueSorted(graph[name].Children)
	}
}

// diffRelations returns the directed edges present in final but not original
// (added) and present in original but not final (removed). Both lists are
// sorted by upstream then downstream.
func diffRelations(original, final adjacency) (added, removed []Relation) {
	origEdges := edgeSet(original)
	finalEdges := edgeSet(final)
	for e := range finalEdges {
		if !origEdges[e] {
			added = append(added, e)
		}
	}
	for e := range origEdges {
		if !finalEdges[e] {
			removed = append(removed, e)
		}
	}
	sortRelations(added)
	sortRelations(removed)
	return added, removed
}

// edgeSet collapses the adjacency into a set of upstream->downstream edges.
func edgeSet(adj adjacency) map[Relation]bool {
	set := make(map[Relation]bool)
	for downstream, parents := range adj {
		for _, upstream := range parents {
			set[Relation{Upstream: upstream, Downstream: downstream}] = true
		}
	}
	return set
}

// sortRelations sorts by upstream then downstream.
func sortRelations(rels []Relation) {
	sort.Slice(rels, func(i, j int) bool {
		if rels[i].Upstream != rels[j].Upstream {
			return rels[i].Upstream < rels[j].Upstream
		}
		return rels[i].Downstream < rels[j].Downstream
	})
}

// affectedDownstreams computes the impact set: starting from the seed datasets
// (new, actually changed, or actually removed), follow downstream (children)
// edges in BOTH the original and the final graphs. Datasets that are
// themselves seeds are excluded from the output; every other reachable dataset
// is included once.
//
// Walking both graphs matters when relations are deleted: a dataset that was
// reachable downstream before the change (and thus loses a lineage path) is
// still affected even if the edge is gone in the final graph. Removed datasets
// are seeds too, so a downstream that lost its upstream node is counted.
func affectedDownstreams(original, final adjacency, newNames, changedNames, removedNames []string) []string {
	seeds := make(map[string]bool, len(newNames)+len(changedNames)+len(removedNames))
	for _, name := range newNames {
		seeds[name] = true
	}
	for _, name := range changedNames {
		seeds[name] = true
	}
	for _, name := range removedNames {
		seeds[name] = true
	}

	origChildren := invertAdjacency(original)
	finalChildren := invertAdjacency(final)

	seen := make(map[string]bool)
	queue := make([]string, 0, len(seeds))
	for seed := range seeds {
		queue = append(queue, seed)
	}
	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]
		for _, child := range origChildren[node] {
			if !seen[child] {
				seen[child] = true
				queue = append(queue, child)
			}
		}
		for _, child := range finalChildren[node] {
			if !seen[child] {
				seen[child] = true
				queue = append(queue, child)
			}
		}
	}

	out := make([]string, 0, len(seen))
	for name := range seen {
		if !seeds[name] {
			out = append(out, name)
		}
	}
	sort.Strings(out)
	return out
}

// invertAdjacency maps each dataset to the datasets that depend on it (its
// children), with each child list sorted by name.
func invertAdjacency(adj adjacency) map[string][]string {
	children := make(map[string][]string, len(adj))
	for name, parents := range adj {
		for _, parent := range parents {
			children[parent] = append(children[parent], name)
		}
	}
	for name := range children {
		sort.Strings(children[name])
	}
	return children
}

// adjacencyToDatasets renders the final adjacency as sorted, JSON-ready
// records with non-nil upstream lists.
func adjacencyToDatasets(adj adjacency) []GraphDataset {
	names := make([]string, 0, len(adj))
	for name := range adj {
		names = append(names, name)
	}
	sort.Strings(names)
	ds := make([]GraphDataset, 0, len(names))
	for _, name := range names {
		parents := adj[name]
		if parents == nil {
			parents = []string{}
		}
		ds = append(ds, GraphDataset{Name: name, Upstreams: parents})
	}
	return ds
}

// stringSliceEqual reports whether a and b contain the same strings in the
// same order. Both are expected to be sorted and duplicate-free.
func stringSliceEqual(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

// MarshalGraphFile serializes the in-memory graph to the on-disk JSON format.
// The graph must be valid; an invalid graph returns an error.
func MarshalGraphFile(graph map[string]*Lineage) ([]byte, error) {
	adj, err := graphAdjacency(graph)
	if err != nil {
		return nil, err
	}
	gf := GraphFile{Datasets: adjacencyToDatasets(adj)}
	return json.MarshalIndent(gf, "", "  ")
}

// UnmarshalGraphFile parses the on-disk graph JSON, rebuilds the in-memory
// graph (parents and children), and validates it. A graph that is structurally
// invalid (empty names, duplicate datasets, missing upstreams, or cycles) is
// rejected so it cannot be used as the basis for a batch.
func UnmarshalGraphFile(data []byte) (map[string]*Lineage, error) {
	var gf GraphFile
	if err := json.Unmarshal(data, &gf); err != nil {
		return nil, fmt.Errorf("invalid graph JSON: %w", err)
	}
	graph := make(map[string]*Lineage, len(gf.Datasets))
	for _, ds := range gf.Datasets {
		if ds.Name == "" {
			return nil, fmt.Errorf("%w: graph contains a dataset with an empty name", ErrInvalidArgument)
		}
		if _, exists := graph[ds.Name]; exists {
			return nil, fmt.Errorf("%w: dataset %q is declared more than once in the graph", ErrInvalidArgument, ds.Name)
		}
		graph[ds.Name] = &Lineage{Dataset: ds.Name, Parents: uniqueSorted(ds.Upstreams)}
	}
	// Rebuild children from the parent edges so the in-memory graph is
	// consistent regardless of how the file was produced.
	for name, entry := range graph {
		for _, parent := range entry.Parents {
			if parentNode, ok := graph[parent]; ok {
				parentNode.Children = append(parentNode.Children, name)
			}
		}
	}
	for name := range graph {
		graph[name].Children = uniqueSorted(graph[name].Children)
	}
	if err := ValidateGraph(graph); err != nil {
		return nil, err
	}
	return graph, nil
}

// UnmarshalPlan parses the plan JSON. The plan structure (empty names,
// duplicate declarations) is validated later by computeBatch so that preview
// and apply share identical rejection behavior.
func UnmarshalPlan(data []byte) (Plan, error) {
	var p Plan
	if err := json.Unmarshal(data, &p); err != nil {
		return p, fmt.Errorf("invalid plan JSON: %w", err)
	}
	return p, nil
}

