549			"long s datasets declared once": `{"formatVersion":1,"contentId":"` + id +
550				`","graph":{"data` + longS + `ets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":["A"]}]}}`,
551			"long s upstreams declared once": `{"formatVersion":1,"contentId":"` + id +
552				`","graph":{"datasets":[{"name":"A","upstreams":[]},{"name":"B","up` + longS + `treams":["A"]}]}}`,
553			"escaped long s version declared once": `{"formatVer` + longSEscape + `ion":1,"contentId":"` + id + `","graph":` + graph + `}`,
554			"same key nested inside unknown field": `{"formatVersion":1,"contentId":"` + id + `","graph":` + graph +
555				`,"meta":{"formatVersion":2,"datasets":null}}`,
556			"fold-spelled key nested inside unknown field": `{"formatVersion":1,"contentId":"` + id + `","graph":` +
557				graph + `,"meta":{"formatVer` + longS + `ion":2,"data` + longS + `ets":[]}}`,
558		}
559		for name, data := range cases {
560			t.Run(name, func(t *testing.T) {
561				parsed, err := ParseSnapshot([]byte(data))
562				if err != nil {
563					t.Fatalf("a field declared once in a fold spelling was rejected: %v", err)
564				}
565				if parsed.ContentID != id {
566					t.Errorf("content id = %s, want %s", parsed.ContentID, id)
567				}
568			})
569		}
570	}
