package chainledger

import (
	"errors"
	"reflect"
	"testing"
)

// TestReadersShareGraphStructureRules is a parity guard for the consolidation:
// the standalone graph file reader and the snapshot graph reader must agree on
// every graph's validity, on the sentinel error category when invalid, and on
// the normalized lineage (via a rebuilt graph file) when valid.
func TestReadersShareGraphStructureRules(t *testing.T) {
	graphs := map[string]string{
		"empty":                 `{"datasets":[]}`,
		"single root":           `{"datasets":[{"name":"A","upstreams":[]}]}`,
		"chain shuffled":        `{"datasets":[{"name":"C","upstreams":["B","A","B"]},{"name":"A","upstreams":[]},{"name":"B","upstreams":["A"]}]}`,
		"case and spaces":       `{"datasets":[{"name":" A ","upstreams":[]},{"name":"a","upstreams":[" A "]}]}`,
		"empty name":            `{"datasets":[{"name":"","upstreams":[]}]}`,
		"duplicate dataset":     `{"datasets":[{"name":"A","upstreams":[]},{"name":"A","upstreams":[]}]}`,
		"missing upstream":      `{"datasets":[{"name":"A","upstreams":["ghost"]}]}`,
		"direct self cycle":     `{"datasets":[{"name":"A","upstreams":["A"]}]}`,
		"indirect cycle":        `{"datasets":[{"name":"A","upstreams":["B"]},{"name":"B","upstreams":["A"]}]}`,
		"empty upstream string": `{"datasets":[{"name":"A","upstreams":[""]}]}`,
	}

	category := func(err error) string {
		switch {
		case err == nil:
			return ""
		case errors.Is(err, ErrInvalidArgument):
			return "invalid"
		case errors.Is(err, ErrNotFound):
			return "notfound"
		case errors.Is(err, ErrCycle):
			return "cycle"
		default:
			return "other"
		}
	}

	for name, data := range graphs {
		t.Run(name, func(t *testing.T) {
			fileGraph, fileErr := UnmarshalGraphFile([]byte(data))

			// Embed the same graph bytes in an otherwise-valid snapshot
			// envelope with a recomputed-or-placeholder id. ParseSnapshot also
			// enforces content-id integrity; to isolate the shared structure
			// rules from that snapshot-only rule, derive the id when the graph
			// is valid and use a dummy one otherwise (structure is checked
			// before the content id).
			snapDoc := `{"formatVersion":1,"contentId":"sha256:deadbeef","graph":` + data + `}`
			_, snapErr := ParseSnapshot([]byte(snapDoc))

			if category(fileErr) != category(snapErr) {
				t.Fatalf("category mismatch: file=%v snapshot=%v", fileErr, snapErr)
			}
			if fileErr != nil {
				return
			}

			// Valid graph: the snapshot reader must keep the same normalized
			// graph as the file reader. Rebuild canonical graph files from
			// each and compare.
			fileBytes, err := MarshalGraphFile(fileGraph)
			if err != nil {
				t.Fatalf("marshal file graph: %v", err)
			}
			snap := snapshotOf(t, data)
			snapGraphBytes, err := jsonMarshalGraphFile(snap.Graph)
			if err != nil {
				t.Fatalf("marshal snapshot graph: %v", err)
			}
			if !reflect.DeepEqual(fileBytes, snapGraphBytes) {
				t.Fatalf("normalized graph differs:\n file %s\n snap %s", fileBytes, snapGraphBytes)
			}
		})
	}
}

func jsonMarshalGraphFile(gf GraphFile) ([]byte, error) {
	return marshalGraphFileBytes(gf)
}

